    DropdownSemanticAllType['classNames'],
    DropdownSemanticAllType['styles'],
    DropdownProps
  >([contextClassNames, classNames], [contextStyles, contextStyleRoot, styles, overlayStyleRoot], {
    props: mergedProps,
  });

